[[reply_to_current]] For a Jest-only mock, yes — but I’d avoid calling/structuring it as a “backdoor” outside tests. Make it an explicit test fixture username, and keep it inside `setupFilesAfterEnv` so it never reaches production code.

Example setup mock:

```ts
// test/setup.ts

const TEST_AUTH_USERNAME = 'test-auth-user';

jest.mock('../src/services/identityAuthService', () => ({
  identityAuthService: {
    authenticate: jest.fn().mockImplementation(async ({ username, password }) => {
      if (username === TEST_AUTH_USERNAME) {
        return {
          success: true,
          user: {
            id: 'test-user-id',
            username: TEST_AUTH_USERNAME,
            email: 'test@example.com',
            roles: ['user'],
          },
          accessToken: 'mock-access-token',
          refreshToken: 'mock-refresh-token',
          expiresIn: 3600,
        };
      }

      return {
        success: false,
        error: 'Invalid credentials',
      };
    }),

    verifyToken: jest.fn().mockResolvedValue({
      success: true,
      user: {
        id: 'test-user-id',
        username: TEST_AUTH_USERNAME,
        email: 'test@example.com',
        roles: ['user'],
      },
    }),

    getUser: jest.fn().mockResolvedValue({
      id: 'test-user-id',
      username: TEST_AUTH_USERNAME,
      email: 'test@example.com',
      name: 'Test User',
    }),

    createSession: jest.fn().mockResolvedValue({
      accessToken: 'mock-access-token',
      refreshToken: 'mock-refresh-token',
      expiresIn: 3600,
    }),

    revokeSession: jest.fn().mockResolvedValue(undefined),
  },
}));
```

